// Extract author name
let author_name = $('.WorkMeta-authors a').text_sane() || null;

// Extract price - combine currency symbol and value
let price_value = $('.WorkSelector-price .price').text_sane();
let currency = 'USD'; // Based on $ symbol in the HTML

// Create Money object if price exists
let price = price_value ? new Money(+price_value, currency) : null;

// Determine availability status based on Add to Cart button presence
let availability_status = $('.AddToCartButton button').length > 0 ? 'In Stock' : 'Out of Stock';

return {
  book_title,
  author_name,
  price,
  availability_status
};

