parser.parser:
// Extract book title
let book_title = $('.WorkMeta-title').text_sane() || null;

// Extract author name
let author_name = $('.WorkMeta-authors a').text_sane() || null;

// Extract price - get currency symbol and value separately for robustness
let currency_symbol = $('.WorkSelector-price span').first().text_sane();
let price_value_text = $('.WorkSelector-price .price').text_sane();

// Determine currency code from symbol
let currency = 'USD';
if (currency_symbol) {
  const currency_map = {'$': 'USD', '€': 'EUR', '£': 'GBP', '¥': 'JPY'};
  currency = currency_map[currency_symbol] || 'USD';
}

// Create Money object if price exists
let price = price_value_text ? new Money(parseFloat(price_value_text), currency) : null;

// Determine availability status based on Add to Cart button presence
let availability_status = $('.AddToCartButton button').length > 0 ? 'In Stock' : 'Out of Stock';

return {
  book_title,
  author_name,
  price,
  availability_status
};

